/bin/zsh -lc "cat > tb_bp.sv <<'EOF'
"'`timescale 1ns/1ps
module tb_bp;
  reg clk=0; always #5 clk=~clk;
  reg rst_n=0;
  reg [7:0] data_in=0;
  reg valid_a=0;
  reg ready_b=0;
  wire ready_a;
  wire valid_b;
  wire [9:0] data_out;
  TopModule dut(.*);

  integer accepted = 0;
  integer errors = 0;

  task drive_until_accept(input [7:0] v);
    begin
      data_in = v;
      valid_a = 1;
      while (!(valid_a && ready_a)) @(negedge clk);
      accepted = accepted + 1;
      @(negedge clk);
      valid_a = 0;
    end
  endtask

  always @(posedge clk) begin
    if (valid_b && ready_b)
      $display("OUT t=%0t data=%0d", $time, data_out);
  end

  initial begin
    ready_b = 1;
    repeat(2) @(negedge clk);
    rst_n = 1;

    drive_until_accept(1);
    drive_until_accept(2);
    drive_until_accept(3);
    drive_until_accept(4);
    @(posedge clk);
    if (!(valid_b && data_out == 10'"'d10)) begin
      "'$display("ERR expected 10, got valid=%0b data=%0d", valid_b, data_out);
      errors = errors + 1;
    end

    ready_b = 0;
    repeat(2) @(negedge clk);
    if (ready_a !== 0) begin
      $display("ERR ready_a should deassert during backpressure");
      errors = errors + 1;
    end
    ready_b = 1;

    drive_until_accept(5);
    drive_until_accept(6);
    drive_until_accept(7);
    drive_until_accept(8);
    @(posedge clk);
    if (!(valid_b && data_out == 10'"'d26)) begin
      "'$display("ERR expected 26, got valid=%0b data=%0d", valid_b, data_out);
      errors = errors + 1;
    end

    @(negedge clk);
    data_in = 8'"'d9;
    valid_a = 1;
    if ("'!ready_a) begin
      $display("ERR ready_a should stay high when output is consumed");
      errors = errors + 1;
    end
    @(negedge clk);
    valid_a = 0;
    if (dut.data_cnt != 2'"'d1) begin
      "'$display("ERR next accumulation did not start after consume");
      errors = errors + 1;
    end

    if (errors == 0) $display("PASS");
    else $display("FAIL errors=%0d", errors);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_bp TopModule.sv tb_bp.sv && vvp simv_bp'

