/bin/zsh -lc "cat > tb_overlap.sv <<'EOF'
"'`timescale 1ns/1ps
module tb_overlap;
  reg clk=0; always #5 clk=~clk;
  reg rst_n=0;
  reg [7:0] data_in=0;
  reg valid_a=0;
  reg ready_b=1;
  wire ready_a;
  wire valid_b;
  wire [9:0] data_out;
  TopModule dut(.*);

  task pulse(input [7:0] v);
    begin
      @(negedge clk); data_in=v; valid_a=1;
      @(negedge clk); valid_a=0;
    end
  endtask

  initial begin
    repeat(2) @(negedge clk);
    rst_n=1;
    pulse(1); pulse(2); pulse(3); pulse(4);
    // On the cycle the output is consumed, also present next input.
    @(negedge clk); data_in=8'"'d5; valid_a=1; ready_b=1;
    @(posedge clk);
    if (dut.data_cnt "'!= 2'"'d1 || dut.sum_acc "'!= 10'"'d5 || valid_b "'!= 0) begin
      $display("FAIL overlap cnt=%0d acc=%0d vb=%0b", dut.data_cnt, dut.sum_acc, valid_b);
      $finish;
    end
    @(negedge clk); valid_a=0;
    $display("PASS");
    $finish;
  end
endmodule
EOF
